fn make_ticket(run: RunId, step: StepIdx, attempt: u16) -> ActionTicket {
    let seq = SeqNo::ZERO;
    let action = ActionId::new(0);
    ActionTicket {
        run,
        step,
        seq,
        action,
        attempt,
        idempotency_key: vb_core::action::compute_action_idempotency_key(run, seq, action),
        capacity: 1,
